// Module 7 — Jenkins and Docker. A Docker-in-Docker daemon over mutual TLS in the lab, the service
// lab/stock-service built, tested, published to the Gitea registry and deployed by a multibranch pipeline;
// every screenshot, console output and error comes from the lab (Jenkins 2.580.2 LTS, Docker 29.10.0,
// 2026-11-17). The code constants are generated from the files that ran.

export const COMPOSE_DOCKER = `  docker:
    image: docker:29.10.0-dind                # Docker Engine in a container: the daemon used by the builds (Module 7)
    container_name: docker
    restart: unless-stopped
    privileged: true                          # required by Docker-in-Docker
    command: ["--insecure-registry=gitea:3000"]   # the image registry of the lab (Gitea) speaks plain HTTP
    environment:
      DOCKER_TLS_CERTDIR: /certs              # generate certificates: the API listens on port 2376 with mutual TLS
    ports:
      - "8090:8090"                           # staging deployments, http://localhost:8090
    volumes:
      - docker_certs:/certs/client            # client certificates, shared with the agent
      - docker_data:/var/lib/docker           # images, layers and build cache survive a restart
      - agent1_work:/home/jenkins/agent       # same workspace paths as agent-1, for docker run -v and agent { docker }
`

export const COMPOSE_AGENT1 = `  agent-1:
    build: ./agent                            # Module 6: official inbound agent + CI tools (agent/Dockerfile)
    image: lab/build-agent:2                  # name of the image built from agent/Dockerfile (2: + Docker CLI, Module 7)
    container_name: agent-1
    restart: unless-stopped
    environment:
      JENKINS_URL: http://jenkins:8080        # the controller, reached by its service name
      JENKINS_AGENT_NAME: agent-1             # must match the node name created in Jenkins
      JENKINS_SECRET: \${AGENT_1_SECRET}       # read from the .env file next to this one (never commit it)
      JENKINS_WEB_SOCKET: "true"              # connect over HTTP WebSocket: no extra port to open
      JENKINS_AGENT_WORKDIR: /home/jenkins/agent
      DOCKER_HOST: tcp://docker:2376          # Module 7: the Docker daemon of the lab, over TLS
      DOCKER_CERT_PATH: /certs/client         # client certificate generated by the docker service
      DOCKER_TLS_VERIFY: "1"
    volumes:
      - agent1_work:/home/jenkins/agent       # workspaces survive a restart of the agent container
      - docker_certs:/certs/client:ro         # Module 7: read-only access to the client certificates
    depends_on:
      - jenkins
      - docker
`

