export const APP_JS = `// lab/stock-service — the HTTP handler: routes of the stock API (no dependencies)
const stock = { bolt: 12, nut: 1, screw: 4 }

export function handler(req, res) {
  const send = (status, body) => {
    res.writeHead(status, { 'content-type': 'application/json' })
    res.end(JSON.stringify(body))
  }
  if (req.method !== 'GET') return send(405, { error: 'method not allowed' })
  if (req.url === '/health') return send(200, { status: 'UP', version: process.env.APP_VERSION ?? 'dev' })
  if (req.url === '/api/stock') return send(200, stock)
  if (req.url === '/api/stock/low') return send(200, Object.keys(stock).filter(item => stock[item] < 5).sort())
  return send(404, { error: 'not found' })
}
`

export const SERVER_JS = `// lab/stock-service — starts the HTTP server
import { createServer } from 'node:http'
import { handler } from './app.js'

const port = Number(process.env.PORT ?? 8080)
const server = createServer(handler)
server.listen(port, () => console.log(\`stock-service \${process.env.APP_VERSION ?? 'dev'} listening on port \${port}\`))
process.on('SIGTERM', () => server.close(() => process.exit(0)))   // docker stop: finish the requests, then exit
`

export const APP_TEST_JS = `import { test, before, after } from 'node:test'
import assert from 'node:assert/strict'
import { createServer } from 'node:http'
import { handler } from '../src/app.js'

let server, base
before(async () => {
  server = createServer(handler)
  await new Promise(resolve => server.listen(0, resolve))   // port 0: any free port
  base = \`http://127.0.0.1:\${server.address().port}\`
})
after(() => server.close())

test('health reports UP', async () => {
  const r = await fetch(\`\${base}/health\`)
  assert.equal(r.status, 200)
  assert.equal((await r.json()).status, 'UP')
})

test('lists the items below 5 units', async () => {
  assert.deepEqual(await (await fetch(\`\${base}/api/stock/low\`)).json(), ['nut', 'screw'])
})

test('unknown route: 404', async () => {
  assert.equal((await fetch(\`\${base}/nope\`)).status, 404)
})
`

export const DOCKERFILE = `# lab/stock-service — Dockerfile: the image of the stock API
FROM node:26.13.1-alpine3.24

ARG APP_VERSION=dev
ENV NODE_ENV=production \\
    APP_VERSION=\${APP_VERSION} \\
    PORT=8080

WORKDIR /app
COPY package.json ./
COPY src/ ./src/

USER node
EXPOSE 8080
HEALTHCHECK --interval=5s --timeout=3s --start-period=5s --retries=3 \\
  CMD wget -qO- http://127.0.0.1:8080/health || exit 1
CMD ["node", "src/server.js"]
`

