export const JF_SERVICE = `// lab/stock-service — Jenkinsfile: test, build, check, publish and deploy a Docker image
pipeline {
    agent { label 'docker' }                                   // agent-1: Docker CLI, DOCKER_HOST=tcp://docker:2376
    options {
        timestamps()
        buildDiscarder(logRotator(numToKeepStr: '10'))
        timeout(time: 20, unit: 'MINUTES')
        disableConcurrentBuilds()                              // one build per branch at a time (one staging)
    }
    environment {
        REGISTRY = 'gitea:3000'                                // the image registry of the lab
        IMAGE    = "\${REGISTRY}/lab/stock-service"
        VERSION  = "1.0.\${env.BUILD_NUMBER}"
    }

    stages {
        stage('Unit tests') {
            agent {
                docker { image 'node:26.13.1-alpine3.24'; reuseNode true }   // tests in a throwaway container
            }
            steps {
                sh 'node --version && npm test'
            }
            post {
                always { junit 'junit.xml' }
            }
        }
        stage('Build image') {
            steps {
                sh '''
                    docker build \\
                      --build-arg APP_VERSION=$VERSION \\
                      --label org.opencontainers.image.version=$VERSION \\
                      --label org.opencontainers.image.revision=$GIT_COMMIT \\
                      --tag $IMAGE:$VERSION \\
                      --tag $IMAGE:sha-$(git rev-parse --short=7 HEAD) \\
                      .
                '''
                sh 'docker image ls $IMAGE'
            }
        }
        stage('Container test') {
            steps {
                sh '''
                    cid=$(docker run -d $IMAGE:$VERSION)                # no fixed name: Docker picks a unique one
                    trap 'docker rm -f $cid > /dev/null' EXIT           # removed even when the test fails
                    for i in $(seq 1 30); do
                      status=$(docker inspect -f '{{.State.Health.Status}}' $cid)
                      echo "health: $status"
                      case $status in healthy|unhealthy) break ;; esac
                      sleep 1
                    done
                    if [ "$status" != healthy ]; then docker logs $cid; exit 1; fi   # show why it failed
                    docker exec $cid wget -qO- http://127.0.0.1:8080/health
                '''
            }
        }
        stage('Publish') {
            when { branch 'main' }
            steps {
                withCredentials([usernamePassword(credentialsId: 'gitea-packages',
                                                  usernameVariable: 'REG_USER', passwordVariable: 'REG_TOKEN')]) {
                    sh '''
                        export DOCKER_CONFIG="$WORKSPACE_TMP/docker-config"   # login for this build only
                        trap 'docker logout $REGISTRY; rm -rf "$DOCKER_CONFIG"' EXIT   # even if a push fails
                        echo "$REG_TOKEN" | docker login $REGISTRY --username "$REG_USER" --password-stdin
                        docker push $IMAGE:$VERSION
                        docker push $IMAGE:sha-$(git rev-parse --short=7 HEAD)
                        docker tag $IMAGE:$VERSION $IMAGE:latest
                        docker push $IMAGE:latest
                    '''
                }
            }
        }
        stage('Deploy to staging') {
            when { branch 'main' }
            steps {
                sh '''
                    docker rm -f stock-service-staging || true
                    docker run -d --name stock-service-staging --restart unless-stopped -p 8090:8080 $IMAGE:$VERSION
                    for i in $(seq 1 30); do
                      curl -fsS http://docker:8090/health && exit 0
                      sleep 1
                    done
                    exit 1
                '''
            }
        }
    }
    post {
        always {
            sh 'docker image prune -f'                          // dangling layers left by previous builds
        }
    }
}
`

export const DSL_EXTRAIT = `        stage('Build image') {
            steps {
                script {                                                                 // Docker Pipeline DSL
                    def image = docker.build("\${IMAGE}:\${VERSION}", "--build-arg APP_VERSION=\${VERSION} .")
                    docker.withRegistry("http://\${REGISTRY}", 'gitea-packages') {
                        image.push('branch-docker-dsl')                                  // a tag for this branch only
                    }
                    image.inside {
                        sh 'node --version && ls /app/src'                               // commands inside the image
                    }
                }
            }
        }
`

export const DOCKER_CLEANUP = `// docker-cleanup — weekly maintenance of the Docker daemon used by the builds (Pipeline job, Module 7)
pipeline {
    agent { label 'docker' }
    triggers { cron('H 3 * * 0') }                                      // every Sunday, around 03:00
    options { timestamps(); buildDiscarder(logRotator(numToKeepStr: '20')) }
    parameters {
        string(name: 'UNTIL', defaultValue: '168h', description: 'Remove unused objects older than this (Docker duration)')
    }
    stages {
        stage('Before') {
            steps { sh 'docker system df' }
        }
        stage('Prune') {
            steps {
                sh 'docker container prune -f --filter "until=\${UNTIL:-168h}"'   // stopped containers (default if no parameter yet)
                sh 'docker image prune -af --filter "until=\${UNTIL:-168h}"'      // images used by no container
                sh 'docker builder prune -f --filter "until=\${UNTIL:-168h}"'     // build cache
            }
        }
        stage('After') {
            steps { sh 'docker system df' }
        }
    }
}
`

